const item = $input.first();
const sender = String(item.json.from ?? '').trim().toLowerCase();
const subject = String(item.json.subject ?? '').trim();
const expectedSubject = "restore ranking";
const subjectMatched = subject.toLowerCase().includes(expectedSubject);
const senderAllowed = sender.endsWith('@example.com');
const binaries = Object.entries(item.binary ?? {});
const csvFiles = binaries.filter(([, file]) => {
  const extension = String(file.fileExtension ?? '').toLowerCase();
  const fileName = String(file.fileName ?? '').toLowerCase();
  const mimeType = String(file.mimeType ?? '').toLowerCase();
  return extension === 'csv' || fileName.endsWith('.csv') || mimeType === 'text/csv';
});
const attachmentValid = csvFiles.length === 1;
let reason = '';
if (!subjectMatched) reason = 'Subject does not match this workflow';
else if (!senderAllowed) reason = 'Sender must use a @example.com email address';
else if (!attachmentValid) reason = csvFiles.length === 0
  ? 'Attach exactly one CSV file containing RoomKey and AccountKey columns'
  : 'Only one CSV attachment can be processed in each email';
const output = {
  json: {
    ...item.json,
    MessageId: String(item.json.id ?? ''),
    RequesterEmail: sender,
    SubjectMatched: subjectMatched,
    SenderAllowed: senderAllowed,
    AttachmentValid: attachmentValid,
    ValidationReason: reason,
    RankingAction: "Restore",
  },
};
if (attachmentValid) output.binary = { data: csvFiles[0][1] };
return [output];

const input = $input.all();
const context = $('Validate Sender Subject and CSV').first().json;
const normalizeHeader = (value) => String(value ?? '').toLowerCase().replace(/[\s_-]+/g, '');
const getValue = (row, expected) => {
  const target = normalizeHeader(expected);
  for (const [key, value] of Object.entries(row ?? {})) {
    if (normalizeHeader(key) === target) return String(value ?? '').trim();
  }
  return '';
};
const firstJson = input[0]?.json ?? {};
if (firstJson.error) {
  return [{ json: {
    RowNumber: 0,
    RequestId: 'PARSE-ERROR',
    RoomKey: '',
    AccountKey: '',
    RankingAction: "Restore",
    TargetScore: 0,
    SalesforceDownranked: false,
    InputValid: false,
    ValidationComment: 'CSV parsing failed: ' + String(firstJson.error),
  }}];
}
const keys = Object.keys(firstJson);
const hasRoomHeader = keys.some((key) => normalizeHeader(key) === 'room_key');
const hasAccountHeader = keys.some((key) => normalizeHeader(key) === 'accountkey');
if (!hasRoomHeader || !hasAccountHeader) {
  return [{ json: {
    RowNumber: 0,
    RequestId: 'HEADER-ERROR',
    RoomKey: '',
    AccountKey: '',
    RankingAction: "Restore",
    TargetScore: 0,
    SalesforceDownranked: false,
    InputValid: false,
    ValidationComment: 'CSV must contain RoomKey and AccountKey columns',
  }}];
}
const dataRows = input
  .map((item, index) => ({ row: item.json ?? {}, index }))
  .filter(({ row }) => Object.values(row).some((value) => String(value ?? '').trim() !== ''));
if (dataRows.length === 0) {
  return [{ json: {
    RowNumber: 0,
    RequestId: 'EMPTY-CSV',
    RoomKey: '',
    AccountKey: '',
    RankingAction: "Restore",
    TargetScore: 0,
    SalesforceDownranked: false,
    InputValid: false,
    ValidationComment: 'CSV contains no data rows',
  }}];
}
const messageToken = String(context.MessageId ?? 'message').replace(/[^a-zA-Z0-9]/g, '').slice(-16) || 'message';
return dataRows.map(({ row, index }) => {
  const roomKey = getValue(row, 'RoomKey');
  const accountKey = getValue(row, 'AccountKey');
  const rowNumber = index + 2;
  return {
    json: {
      RowNumber: rowNumber,
      RequestId: "RESTORE" + '-' + messageToken + '-' + rowNumber,
      RoomKey: roomKey,
      AccountKey: accountKey,
      RankingAction: "Restore",
      TargetScore: 0,
      SalesforceDownranked: false,
      InputValid: Boolean(roomKey),
      ValidationComment: roomKey ? 'Input validated' : 'RoomKey is missing',
    },
    pairedItem: { item: index },
  };
});

const request = $('Normalize CSV Rows').item.json;
let branchKey = '';
try { branchKey = String($('Read Score and BranchKey').item.json.BranchKey ?? ''); } catch {}
return [{ json: {
