const results = $input.all().map((item) => item.json);
const total = results.length;
const rankingUpdated = results.filter((row) => String(row.RankingStatus) === 'Succeeded').length;
const salesforceUpdated = results.filter((row) => String(row.SalesforceStatus).startsWith('Updated')).length;
