      'Salesforce skipped because AccountKey was missing: ' + salesforceSkipped,
      'Rows requiring review: ' + reviewRequired,
      '',
      'The detailed results are attached.',
    ].join('\n');
return [{ json: {
  MessageId: String($('Validate Sender Subject and CSV').first().json.MessageId ?? ''),
  ReplyText: replyText,
  ResultsFileName: "restore_ranking_results.csv",
  Results: results,
}}];

